// quickly find the index of chars within Constants.HEX_DIGITS
private static int getHexByteIndex(byte value) {
    // ['0'-'9'] maps to [0-9] indexes
    if (value >= '0' && value <= '9') {
        return value - '0';
    }
    // ['A'-'F'] maps to [10-15] indexes
    return (value - 'A') + HEX_DIGIT_A_DECIMAL_VALUE;
}
